    return score

def get_screening_and_diagnostic_tests_priority(patient):
    """
    Compute the screening and diagnostic tests priority of the patient.
    patient: A patient object with attributes: resource_availability (boolean), income_level (str), symptoms (list of str), severity (int), age (int), duration_of_condition (int), comorbidities (int)
    Returns: int
    """
    score = 0

    # Higher resource availability increases priority
    if patient.resource_availability:
