    Compute the complementary therapies priority of the patient.

    Parameters:
        patient: A patient object with attributes:
            - comorbidities (int): Number of comorbidities
            - duration_of_condition (int): Duration of condition in months
            - symptoms (list): List of symptoms
            - severity (int): Patient's condition severity (1-10)
            - age (int): Age of the patient
            - resource_availability (str): Resource availability (high, medium, low)
            - income_level (str): Income level (high, medium, low)

    Returns:
        int: Complementary therapy priority score (0-15)
    """
    score = 0

    # Comorbidities
    if patient.comorbidities >= 3:
        score += 3
    elif patient.comorbidities >= 1:
        score += 2

    # Duration of condition
    if patient.duration_of_condition > 24:
        score += 3
    elif 12 < patient.duration_of_condition <= 24:
        score += 2
    elif patient.duration_of_condition > 3:
        score += 1

    # Symptoms
    if 'chronic pain' in patient.symptoms:
        score += 3
    elif 'reduced mobility' in patient.symptoms or 'ongoing fatigue' in patient.symptoms:
        score += 2
    else:
        score += 1

    # Severity
    if patient.severity >= 7:
        score += 3
    elif 4 <= patient.severity < 7:
        score += 2
    else:
        score += 1

    # Age
    if 45 <= patient.age <= 65:
        score += 2
    elif patient.age > 65:
        score += 1

    # Resource availability
    if patient.resource_availability == 'high':
        score += 2
    elif patient.resource_availability == 'medium':
        score += 1

    # Income level
    if patient.income_level == 'high':
        score += 2
    elif patient.income_level == 'medium':
        score += 1

    return score

